// Static Latin instances derived from the app's variable webfonts — SIL OFL 1.1
// Bricolage Grotesque 700/opsz 96:
// packages/worker/public/fonts/bricolage-grotesque-latin.woff2
// https://fonts.google.com/specimen/Bricolage+Grotesque
// Wix Madefor Text 400:
// packages/worker/public/fonts/wix-madefor-text-latin.woff2
// https://fonts.google.com/specimen/Wix+Madefor+Text
const BRICOLAGE_GROTESQUE_LATIN_700_OPSZ_96_TTF_BASE64 =
	''

const WIX_MADEFOR_TEXT_LATIN_400_TTF_BASE64 =
	''

function decodeBase64Font(base64: string): ArrayBuffer {
	const binary = atob(base64)
	const bytes = new Uint8Array(binary.length)
	for (let index = 0; index < binary.length; index += 1) {
		bytes[index] = binary.charCodeAt(index)
	}
	return bytes.buffer
}

let bricolageGrotesqueLatin700FontData: ArrayBuffer | null = null

export function getBricolageGrotesqueLatin700FontData(): ArrayBuffer {
	if (bricolageGrotesqueLatin700FontData) {
		return bricolageGrotesqueLatin700FontData
	}
	bricolageGrotesqueLatin700FontData = decodeBase64Font(
		BRICOLAGE_GROTESQUE_LATIN_700_OPSZ_96_TTF_BASE64,
	)
	return bricolageGrotesqueLatin700FontData
}

let wixMadeforTextLatin400FontData: ArrayBuffer | null = null

export function getWixMadeforTextLatin400FontData(): ArrayBuffer {
	if (wixMadeforTextLatin400FontData) {
		return wixMadeforTextLatin400FontData
	}
	wixMadeforTextLatin400FontData = decodeBase64Font(
		WIX_MADEFOR_TEXT_LATIN_400_TTF_BASE64,
	)
	return wixMadeforTextLatin400FontData
}
